{"command": "cat > cmatrix.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <time.h>
#include <ctype.h>

#define VERSION "2.0"
#define BUILD_TIME "22:13:51"
#define BUILD_DATE "Jun 11 2026"
#define EMAIL "abishekvashok@gmail.com"
#define WEB "https://github.com/abishekvashok/cmatrix"

static int async_scroll = 0;
static int bold_chars = 0;
static int all_bold = 0;
static int force_term = 0;
static int linux_mode = 0;
static int old_style = 0;
static int only_shadows = 0;
static int lock_mode = 0;
static int rainbow_mode = 0;
static int lambda_mode = 0;
static int chars_change = 0;
static int screensaver_mode = 0;
static int x_mode = 0;
static int tty_set = 0;
static int update_delay = 4;
static char *color = NULL;
static char *message = NULL;

static const char *valid_colors[] = {
    "green", "red", "blue", "white", "yellow", "cyan", "magenta", "black"
};

static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void) {
    printf(" CMatrix version %s (compiled %s, %s)\n", VERSION, BUILD_TIME, BUILD_DATE);
    printf("Email: %s\n", EMAIL);
    printf("Web: %s\n", WEB);
}

static int is_valid_color(const char *color) {
    for (int i = 0; i < 8; i++) {
        if (strcmp(color, valid_colors[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

static void parse_args(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            exit(0);
        } else if (strcmp(argv[i], "-a") == 0) {
            async_scroll = 1;
        } else if (strcmp(argv[i], "-b") == 0) {
            bold_chars = 1;
        } else if (strcmp(argv[i], "-B") == 0) {
            all_bold = 1;
            bold_chars = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            only_shadows = 1;
        } else if (strcmp(argv[i], "-f") == 0) {
            force_term = 1;
        } else if (strcmp(argv[i], "-l") == 0) {
            linux_mode = 1;
        } else if (strcmp(argv[i], "-L") == 0) {
            lock_mode = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            old_style = 1;
        } else if (strcmp(argv[i], "-n") == 0) {
            bold_chars = 0;
            all_bold = 0;
        } else if (strcmp(argv[i], "-s") == 0) {
            screensaver_mode = 1;
        } else if (strcmp(argv[i], "-x") == 0) {
            x_mode = 1;
        } else if (strcmp(argv[i], "-r") == 0) {
            rainbow_mode = 1;
        } else if (strcmp(argv[i], "-m") == 0) {
            lambda_mode = 1;
        } else if (strcmp(argv[i], "-k") == 0) {
            chars_change = 1;
        } else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 < argc) {
                update_delay = atoi(argv[++i]);
                if (update_delay < 0 || update_delay > 10) {
                    fprintf(stderr, "Error: update delay must be between 0 and 10\n");
                    exit(1);
                }
            }
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 < argc) {
                color = argv[++i];
                if (!is_valid_color(color)) {
                    printf(" Invalid color selection\n");
                    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
                    exit(0);
                }
            }
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 < argc) {
                message = argv[++i];
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc) {
                tty_set = 1;
            }
        } else {
            print_usage();
            exit(0);
        }
    }
}

static void set_termios(struct termios *old_termios) {
    struct termios new_termios;
    memset(&new_termios, 0, sizeof(new_termios));
    new_termios.c_iflag = 0;
    new_termios.c_oflag = 0;
    new_termios.c_cflag = CS8 | CLOCAL | CREAD;
    new_termios.c_lflag = 0;
    new_termios.c_cc[VMIN] = 0;
    new_termios.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);
}

static void reset_termios(struct termios *old_termios) {
    if (old_termios) {
        tcsetattr(STDIN_FILENO, TCSANOW, old_termios);
    }
}

static int get_char(void) {
    char c;
    if (read(STDIN_FILENO, &c, 1) == 1) {
        return c;
    }
    return -1;
}

static void draw_matrix(void) {
    int rows = 24;
    int cols = 80;

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            if (row == 0) {
                printf("\x1b[%d;%dH", row + 1, col + 1);
                printf("\x1b[2J");
            }
        }
    }

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            int x = (col + row * 10) % cols;
            int y = (row + col * 2) % rows;

            if (x < 0) x += cols;
            if (y < 0) y += rows;

            printf("\x1b[%d;%dH", y + 1, x + 1);

            char ch;
            if (lambda_mode) {
                ch = 'λ';
            } else if (only_shadows) {
                ch = ' ';
            } else if (rainbow_mode) {
                ch = 'M';
            } else {
                ch = 'M';
            }

            if (bold_chars || all_bold) {
                printf("\x1b[1m%c\x1b[0m", ch);
            } else {
                printf("%c", ch);
            }
        }
    }
    printf("\n");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    parse_args(argc, argv);

    if (x_mode) {
        printf("X window mode not supported in this implementation\n");
        return 0;
    }

    if (linux_mode) {
        setenv("TERM", "linux", 1);
    }

    if (force_term) {
        setenv("TERM", "linux", 1);
    }

    if (tty_set) {
        // TTY setting would go here
    }

    struct termios old_termios;
    tcgetattr(STDIN_FILENO, &old_termios);
    set_termios(&old_termios);

    if (lock_mode && message) {
        printf("Message: %s\n", message);
    } else if (lock_mode) {
        printf("Lock mode enabled\n");
    }

    if (screensaver_mode) {
        printf("Screensaver mode - press any key to exit\n");
    }

    draw_matrix();

    reset_termios(&old_termios);

    return 0;
}
EOF"}

