                    opts.update_delay = key - '0';
                } else if (key == '!') {
                    color = 1;
                } else if (key == '@') {
                    color = 2;
                } else if (key == '#') {
                    color = 5;
                } else if (key == '$') {
                    color = 3;
                } else if (key == '%') {
                    color = 7;
                } else if (key == '^') {
                    color = 6;
                } else if (key == '&') {
                    color = 4;
                } else if (key == ')') {
                    color = 0;
                }
            }
        }

        sleep_ms(1000 / (opts.update_delay + 1));
    }

    reset_termios(&old_termios);
    return 0;
}
EOF"}

